import { stdout } from std.io;
class Leaf {
    v: Int32;
    construct(v: Int32) { this.v = v; }
}
class Tree {
    name: String;
    leaf: Leaf;
    construct(name: String, leaf: Leaf) { this.name = name; this.leaf = leaf; }
}
fn main(): Void {
    mut a = Tree("t", Leaf(1));
    mut b = a.clone();
    b.leaf.v = 9;
    b.name = "copy";
    stdout.println(a.leaf.v);
    stdout.println(b.leaf.v);
    stdout.println(a.name);
    stdout.println(b.name);
    stdout.println(a is b);
    stdout.println(a.leaf is b.leaf);
}
